import { scenarioFileSchema, scenarioIndexSchema } from '../engine/schemas.ts'
import type { ScenarioFile, ScenarioIndex } from '../engine/index.ts'

// Scenario files are generated by tools/simulator and served with the site.
// These are same-origin requests for bundled files, never a call to another
// service, and every file is validated before it reaches the store.

function seedUrl(name: string): string {
  return `${import.meta.env.BASE_URL}seed/${name}.json`
}

async function fetchJson(url: string): Promise<unknown> {
  const response = await fetch(url)
  if (!response.ok) {
    throw new Error(`Could not load ${url} (HTTP ${response.status})`)
  }
  return response.json()
}

export async function fetchScenario(scenarioId: string): Promise<ScenarioFile> {
  return scenarioFileSchema.parse(await fetchJson(seedUrl(scenarioId)))
}

export async function fetchScenarioIndex(): Promise<ScenarioIndex> {
  return scenarioIndexSchema.parse(await fetchJson(seedUrl('index')))
}

export const DEFAULT_SCENARIO_ID = 'sleep-debt'
